  "trans.conselho.title": "Conselho Fiscal",
  "trans.conselho.p1": "O Conselho Fiscal da ACURA BRASIL é responsável pela fiscalização contábil, financeira, orçamentária, operacional e patrimonial da entidade, em conformidade com o estatuto social e a legislação aplicável às OSCIPs.",
  "trans.conselho.p2": "Para informações sobre a composição do Conselho Fiscal ou solicitação de documentos, entre em <a href=\"contato.html\" style=\"color: var(--azul-institucional); font-weight: 500;\">contato conosco</a>.",
  "trans.cadastro.title": "Informações Cadastrais",
  "trans.cadastro.razao.title": "Razão Social",
  "trans.cadastro.razao.value": "ACURA BRASIL — Associação Brasil pela Cura",
  "trans.cadastro.cnpj.title": "CNPJ",
  "trans.cadastro.cnpj.value": "30.350.850/0001-80",
  "trans.cadastro.nature.title": "Natureza Jurídica",
